<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/attendance-schema.php';ensureAttendanceTimeOutColumn($conn);require '../includes/teacher-profile-schema.php';ensureTeacherProfileColumns($conn);
$section=trim($_GET['section']??'all');$date=$_GET['date']??date('Y-m-d');$student=trim($_GET['student']??'');
$teacherId=(int)($_SESSION['teacher-id']??0);$teacherQuery=$conn->prepare('SELECT GRADE FROM teachers WHERE TEACHER_ID=? LIMIT 1');$teacherQuery->bind_param('i',$teacherId);$teacherQuery->execute();$teacherGrade=(int)(($teacherQuery->get_result()->fetch_assoc()?:[])['GRADE']??0);if(!in_array($teacherGrade,[7,8,9,10,11,12],true)){http_response_code(403);exit('Your teacher account does not have an assigned grade.');}
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))exit('Invalid date.');
$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,s.GRADE,s.SECTION,a.TIME_IN,a.TIME_OUT FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) WHERE DATE(a.TIME_IN)=? AND (?='all' OR s.SECTION=?) AND (?='' OR a.STUDENT_ID=?) AND s.GRADE=? ORDER BY s.SECTION,STUDENT_NAME");
$stmt->bind_param('sssssi',$date,$section,$section,$student,$student,$teacherGrade);$stmt->execute();$result=$stmt->get_result();
if($result->num_rows):while($row=$result->fetch_assoc()):$timeIn=new DateTime($row['TIME_IN']);$timeOut=empty($row['TIME_OUT'])?null:new DateTime($row['TIME_OUT']);?><tr><td class="px-4 py-4"><?= htmlspecialchars($row['STUDENT_ID']) ?></td><td class="px-4 py-4 font-bold"><?= htmlspecialchars($row['STUDENT_NAME']) ?></td><td class="px-4 py-4"><span class="rounded-full bg-violet-50 px-3 py-1 text-xs font-bold text-violet-700">Grade <?= htmlspecialchars($row['GRADE']??'—') ?></span></td><td class="px-4 py-4"><a class="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700 hover:bg-blue-100" href="students.php?section=<?= urlencode($row['SECTION']) ?>"><?= htmlspecialchars($row['SECTION']) ?></a></td><td class="px-4 py-4"><?= $timeIn->format('F j, Y') ?></td><td class="px-4 py-4"><?= $timeIn->format('g:i A') ?></td><td class="px-4 py-4"><?= $timeOut?$timeOut->format('g:i A'):'—' ?></td><td class="px-4 py-4"><?php if($timeOut): ?><span class="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-700">Dismissed</span><?php else: ?><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Present</span><?php endif; ?></td></tr><?php endwhile;else:?><tr><td colspan="8" class="px-4 py-10 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?>
